const home=document.getElementById('home'), levels=document.getElementById('levels'), modal=document.getElementById('caseModal'), grid=document.getElementById('levelGrid');
const progressKey='mysteryProgressV3', doneKey='mysteryCompletedV3';
let unlocked=Math.max(1,Math.min(100,Number(localStorage.getItem(progressKey))||1));
let completed=JSON.parse(localStorage.getItem(doneKey)||'[]'), activeLevel=1, activeTier='Todos';
function showHome(){home.classList.remove('hidden');levels.classList.add('hidden');modal.classList.add('hidden');document.body.style.overflow='';}
function showLevels(){home.classList.add('hidden');levels.classList.remove('hidden');modal.classList.add('hidden');document.body.style.overflow='';renderLevels();}
function renderLevels(){document.getElementById('progressText').textContent=`${completed.length} / 100`;document.getElementById('progressBar').style.width=`${completed.length}%`;let visible=cases.filter(c=>activeTier==='Todos'||c.difficulty===activeTier);document.getElementById('levelCount').textContent=`${visible.length} EXPEDIENTES`;grid.innerHTML='';visible.forEach(item=>{let n=item.id,b=document.createElement('button');b.className='level'+(completed.includes(n)?' completed':'');b.disabled=n>unlocked;b.innerHTML=`<strong>#${String(n).padStart(3,'0')}</strong><small>${item.difficulty.toUpperCase()} · ${completed.includes(n)?'RESUELTO':n<=unlocked?'DISPONIBLE':'BLOQUEADO'}</small><span class="level-state">${completed.includes(n)?'✓':n<=unlocked?'↗':'▣'}</span>`;b.onclick=()=>openCase(n);grid.appendChild(b);});}
document.querySelectorAll('.difficulty').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.difficulty').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeTier=b.dataset.tier;renderLevels();}));
function openCase(n){activeLevel=n;let c=cases[n-1];document.getElementById('levelNumber').textContent=`CASO ${String(n).padStart(3,'0')}`;document.getElementById('difficultyLabel').textContent=`DIFICULTAD ${c.difficulty.toUpperCase()}`;document.getElementById('caseTitle').textContent=c.title;document.getElementById('caseDescription').textContent=c.description;let clues=document.getElementById('clues');clues.innerHTML='';c.clues.forEach((v,i)=>{let d=document.createElement('div');d.className='clue';let tag=document.createElement('b');tag.textContent=`EVIDENCIA 0${i+1}`;d.append(tag,document.createTextNode(v));clues.append(d);});let answers=document.getElementById('answers');answers.innerHTML='';c.answers.forEach((v,i)=>{let b=document.createElement('button');b.className='answer-option';b.textContent=v;b.onclick=()=>checkAnswer(i,c,b);answers.append(b);});document.getElementById('feedback').textContent='';document.getElementById('feedback').className='feedback';document.getElementById('explanation').classList.add('hidden');document.getElementById('nextButton').classList.add('hidden');modal.classList.remove('hidden');document.body.style.overflow='hidden';document.querySelector('.case-window').scrollTop=0;}
function checkAnswer(choice,c,chosen){let feedback=document.getElementById('feedback'),buttons=[...document.querySelectorAll('.answer-option')];if(choice===c.correct){buttons.forEach(b=>b.disabled=true);feedback.textContent='CASO RESUELTO. Tu deducción coincide con las pruebas.';feedback.classList.add('good');if(!completed.includes(activeLevel))completed.push(activeLevel);if(activeLevel===unlocked&&unlocked<100)unlocked++;localStorage.setItem(progressKey,String(unlocked));localStorage.setItem(doneKey,JSON.stringify(completed));let exp=document.getElementById('explanation');exp.textContent='ANÁLISIS: '+c.explanation;exp.classList.remove('hidden');document.getElementById('nextButton').classList.remove('hidden');}else{feedback.textContent='Esa teoría no encaja con todas las evidencias. Volvé a analizarlas.';feedback.classList.remove('good');chosen.disabled=true;}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.classList.contains('hidden'))showLevels();});showHome();
